CREATE TABLE IF NOT EXISTS workflow_definitions(workflow_id TEXT NOT NULL,tenant_id TEXT NOT NULL,version INTEGER NOT NULL,definition_json TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,PRIMARY KEY(workflow_id,version));CREATE TABLE IF NOT EXISTS workflow_runs(run_id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,workflow_id TEXT NOT NULL,workflow_version INTEGER NOT NULL,state TEXT NOT NULL,checkpoint_json TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS idempotency_records(tenant_id TEXT NOT NULL,operation TEXT NOT NULL,idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,status TEXT NOT NULL,response_ref TEXT,expires_at TEXT NOT NULL,PRIMARY KEY(tenant_id,operation,idempotency_key));